return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'','pot-creation-date'=>'2026-06-17T11:18:11+00:00','po-revision-date'=>'2026-05-24T17:14:30+00:00','messages'=>['BrikPanel: WooCommerce Admin Dashboard Theme'=>'BrikPanel: WooCommerce Admin-Dashboard-Theme','Beautiful and modern Shopify-style WooCommerce admin panel & dashboard, fully free, forever.'=>'Schönes und modernes WooCommerce-Adminpanel und -Dashboard im Shopify-Stil, vollständig kostenlos, für immer.','Brksoft'=>'Brksoft','https://brksoft.com/'=>'https://brksoft.com/','WooCommerce is not active on this site, so BrikPanel features are disabled here. Activate WooCommerce to enable BrikPanel.'=>'WooCommerce ist auf dieser Seite nicht aktiv, daher sind die BrikPanel-Funktionen hier deaktiviert. Aktivieren Sie WooCommerce, um BrikPanel zu aktivieren.','Order statusReturn Draft'=>'Retouren-Entwurf','Return Draft <span class="count">(%s)</span>'=>'Retouren-Entwurf <span class="count">(%s)</span>' . "\0" . 'Retouren-Entwürfe <span class="count">(%s)</span>','Order statusChange'=>'Umtausch','Change <span class="count">(%s)</span>'=>'Umtausch <span class="count">(%s)</span>' . "\0" . 'Umtäusche <span class="count">(%s)</span>','%d hidden notice'=>'%d ausgeblendeter Hinweis' . "\0" . '%d ausgeblendete Hinweise','Other plugins and themes posted these notices. BrikPanel keeps them hidden, click to show.'=>'Andere Plugins und Themes haben diese Hinweise erzeugt. BrikPanel hält sie ausgeblendet, zum Anzeigen klicken.','Settings'=>'Einstellungen','Ad Platforms integration'=>'Ad Platforms-Integration','Pull daily ad spend from Google Ads and Meta Ads to calculate true ROAS and Net Profit on the dashboard. Currently in beta. Turn it off below to hide the admin page and stop all background sync jobs. Your connections stay saved.'=>'Rufen Sie die täglichen Werbeausgaben von Google Ads und Meta Ads ab, um auf dem Dashboard den echten ROAS und Nettogewinn zu berechnen. Derzeit in der Beta-Phase. Schalten Sie es unten aus, um die Verwaltungsseite auszublenden und alle Hintergrund-Synchronisationen zu stoppen. Ihre Verbindungen bleiben gespeichert.','Enable Ad Platforms integration'=>'Ad Platforms-Integration aktivieren','When on, the Ad Platforms admin menu, daily sync, and dashboard ROAS / Net Profit cards are active. When off, the module is dormant: no menu item, no scheduled sync, no dashboard cards.'=>'Wenn aktiviert, sind das Ad Platforms-Adminmenü, die tägliche Synchronisierung und die ROAS-/Nettogewinn-Karten im Dashboard aktiv. Wenn deaktiviert, ist das Modul inaktiv: kein Menüeintrag, keine geplante Synchronisierung, keine Dashboard-Karten.','Integrations'=>'Integrationen','Beta'=>'Beta','ROAS'=>'ROAS','Revenue / Ad spend'=>'Umsatz / Werbeausgaben','Ad currency differs from store'=>'Werbewährung weicht vom Shop ab','Google Ads connection was revoked for security. Please reconnect.'=>'Google Ads-Verbindung wurde aus Sicherheitsgründen widerrufen. Bitte verbinden Sie sich erneut.','Not connected to Google Ads.'=>'Nicht mit Google Ads verbunden.','The BrikPanel proxy returned an unverifiable response and was rejected.'=>'Der BrikPanel-Proxy hat eine nicht verifizierbare Antwort zurückgegeben und wurde abgelehnt.','Request to Google Ads failed after retries.'=>'Anfrage an Google Ads ist nach Wiederholungen fehlgeschlagen.','Meta Ads connection was revoked for security. Please reconnect.'=>'Meta Ads-Verbindung wurde aus Sicherheitsgründen widerrufen. Bitte verbinden Sie sich erneut.','Not connected to Meta Ads.'=>'Nicht mit Meta Ads verbunden.','Request to Meta Ads failed after retries.'=>'Anfrage an Meta Ads ist nach Wiederholungen fehlgeschlagen.','Permission denied.'=>'Zugriff verweigert.','Unknown platform.'=>'Unbekannte Plattform.','This connection is not available yet, it is pending platform approval.'=>'Diese Verbindung ist noch nicht verfügbar, sie wartet auf die Freigabe durch die Plattform.','Could not reach the BrikPanel proxy. Please try again in a moment.'=>'Der BrikPanel-Proxy konnte nicht erreicht werden. Bitte versuchen Sie es gleich erneut.','Could not start OAuth: proxy returned an error.'=>'OAuth konnte nicht gestartet werden: Proxy hat einen Fehler zurückgegeben.','Disconnected.'=>'Getrennt.','OAuth session expired. Please try connecting again.'=>'OAuth-Sitzung abgelaufen. Bitte versuchen Sie erneut, sich zu verbinden.','Unknown platform in OAuth state.'=>'Unbekannte Plattform im OAuth-Status.','OAuth callback was for a different user. Aborted.'=>'OAuth-Callback war für einen anderen Benutzer. Abgebrochen.','Could not reach the BrikPanel proxy.'=>'Der BrikPanel-Proxy konnte nicht erreicht werden.','OAuth redemption failed. Please try connecting again.'=>'OAuth-Einlösung fehlgeschlagen. Bitte versuchen Sie erneut, sich zu verbinden.','Could not save tokens. Please try again.'=>'Tokens konnten nicht gespeichert werden. Bitte versuchen Sie es erneut.','Google Ads connected.'=>'Google Ads verbunden.','Meta Ads connected.'=>'Meta Ads verbunden.','Ad Platforms'=>'Ad Platforms','Beta feature'=>'Beta-Funktion','Connecting…'=>'Verbinden…','Disconnect this platform? Your synced spend data will be deleted.'=>'Diese Plattform trennen? Ihre synchronisierten Ausgabendaten werden gelöscht.','Syncing…'=>'Synchronisierung läuft…','Sync queued. Refresh the page in a moment.'=>'Synchronisierung in Warteschlange. Aktualisieren Sie die Seite in Kürze.','Saved.'=>'Gespeichert.','Loading accounts…'=>'Konten werden geladen…','No ad accounts found for this connection.'=>'Keine Werbekonten für diese Verbindung gefunden.','Something went wrong. Please try again.'=>'Etwas ist schiefgelaufen. Bitte versuchen Sie es erneut.','No errors logged.'=>'Keine Fehler protokolliert.','Connected'=>'Verbunden','Not connected'=>'Nicht verbunden','Pick a primary account first.'=>'Wählen Sie zuerst ein Hauptkonto aus.','Manager'=>'Manager','Loading history… %1$d of %2$d 90-day chunks done'=>'Verlauf wird geladen… %1$d von %2$d 90-Tage-Blöcken fertig','Just now'=>'Gerade eben','Google Ads'=>'Google Ads','Meta Ads'=>'Meta Ads','Loading imported data…'=>'Importierte Daten werden geladen…','No spend data imported yet. It appears here once the first sync or backfill completes.'=>'Es wurden noch keine Ausgabendaten importiert. Sie erscheinen hier, sobald die erste Synchronisation oder Nacherfassung abgeschlossen ist.','Could not load imported data.'=>'Importierte Daten konnten nicht geladen werden.','Account %s'=>'Konto %s','%1$s to %2$s'=>'%1$s bis %2$s','%s days with spend'=>'%s Tage mit Ausgaben','Total spend'=>'Gesamtausgaben','Impressions'=>'Impressionen','Clicks'=>'Klicks','Avg CTR'=>'Durchschn. CTR','Avg CPC'=>'Durchschn. CPC','Avg CPM'=>'Durchschn. CPM','Month'=>'Monat','Spend'=>'Ausgaben','CTR'=>'CTR','CPC'=>'CPC','Days'=>'Tage','All time'=>'Gesamtzeit','Connect this platform first.'=>'Verbinden Sie zuerst diese Plattform.','Pick an account before saving.'=>'Wählen Sie ein Konto aus, bevor Sie speichern.','Account saved. Loading 3 years of history in the background. Refresh the page in a few minutes to see it.'=>'Konto gespeichert. Es werden 3 Jahre Verlauf im Hintergrund geladen. Aktualisieren Sie die Seite in einigen Minuten, um ihn zu sehen.','Account saved.'=>'Konto gespeichert.','Synced %1$d row(s) across %2$d day(s).'=>'%1$d Zeile(n) über %2$d Tag(e) synchronisiert.','Ad spend daily sync'=>'Tägliche Synchronisierung der Werbeausgaben','Pulls yesterday plus the last 7 days of spend from each connected ad platform.'=>'Ruft gestern plus die letzten 7 Tage Ausgaben von jeder verbundenen Werbeplattform ab.','Ad spend backfill chunk'=>'Werbeausgaben-Backfill-Block','One 90-day slice of the initial historical pull when an ad platform is first connected.'=>'Ein 90-Tage-Ausschnitt des anfänglichen historischen Abrufs, wenn eine Werbeplattform zum ersten Mal verbunden wird.','Not connected.'=>'Nicht verbunden.','Pending Google approval'=>'Warten auf Google-Genehmigung','Google Ads needs to approve our API access before this connection can go live. It will be enabled automatically once approved. No action is needed from you.'=>'Google Ads muss unseren API-Zugriff genehmigen, bevor diese Verbindung aktiv werden kann. Sie wird nach der Genehmigung automatisch aktiviert. Es ist keine Aktion Ihrerseits erforderlich.','Connect Google Ads'=>'Google Ads verbinden','Pending Meta approval'=>'Warten auf Meta-Genehmigung','Meta needs to review our app before this connection can go live. It will be enabled automatically once approved. No action is needed from you.'=>'Meta muss unsere App prüfen, bevor diese Verbindung aktiv werden kann. Sie wird nach der Genehmigung automatisch aktiviert. Es ist keine Aktion Ihrerseits erforderlich.','Connect Meta Ads'=>'Meta Ads verbinden','Coming soon'=>'Demnächst verfügbar','BrikPanel will request read-only access to your Google Ads accounts. We only pull total daily spend, impressions and clicks. No campaign management.'=>'BrikPanel fordert nur Lesezugriff auf Ihre Google Ads-Konten an. Wir rufen nur die gesamten täglichen Ausgaben, Impressionen und Klicks ab. Keine Kampagnenverwaltung.','BrikPanel will request read-only access (ads_read) to your Meta ad accounts. We only pull total daily spend, impressions and clicks.'=>'BrikPanel fordert schreibgeschützten Zugriff (ads_read) auf Ihre Meta-Werbekonten an. Wir rufen nur die täglichen Gesamtausgaben, Impressionen und Klicks ab.','Connected as'=>'Verbunden als','(email not shared)'=>'(E-Mail nicht freigegeben)','Primary ad account'=>'Haupt-Werbekonto','BrikPanel pulls spend from this one account. To switch later, choose another from the list and click Save.'=>'BrikPanel ruft Ausgaben von diesem einen Konto ab. Um später zu wechseln, wählen Sie ein anderes aus der Liste und klicken Sie auf Speichern.','Click "Load accounts" to choose…'=>'Klicken Sie auf "Konten laden", um auszuwählen…','Load accounts'=>'Konten laden','Save'=>'Speichern','Manager (MCC) account ID (optional)'=>'Verwaltungskonto-ID (MCC) (optional)','Only fill in if you access the chosen account through a Google Ads manager. Digits only, no dashes.'=>'Nur ausfüllen, wenn Sie auf das gewählte Konto über einen Google Ads-Manager zugreifen. Nur Ziffern, keine Bindestriche.','Last successful sync'=>'Letzte erfolgreiche Synchronisierung','ago'=>'her','(last attempt failed, check the error log)'=>'(letzter Versuch fehlgeschlagen, prüfen Sie das Fehlerprotokoll)','Sync now'=>'Jetzt synchronisieren','Re-authorize'=>'Erneut autorisieren','Disconnect'=>'Trennen','Connect Google Ads and Meta Ads so BrikPanel can show real ROAS and Net Profit on the dashboard.'=>'Verbinden Sie Google Ads und Meta Ads, damit BrikPanel echtes ROAS und Nettogewinn im Dashboard anzeigen kann.','Pulls daily total spend, impressions and clicks from one Google Ads account.'=>'Ruft tägliche Gesamtausgaben, Impressionen und Klicks von einem Google Ads-Konto ab.','Pulls daily total spend, impressions and clicks from one Meta ad account (Facebook + Instagram).'=>'Ruft tägliche Gesamtausgaben, Impressionen und Klicks von einem Meta-Werbekonto ab (Facebook + Instagram).','Imported spend data'=>'Importierte Ausgabendaten','Everything BrikPanel has pulled so far, broken down by month. This is the raw data behind the dashboard ROAS and Net Profit figures.'=>'Alles, was BrikPanel bisher abgerufen hat, nach Monaten aufgeschlüsselt. Dies sind die Rohdaten hinter den ROAS- und Nettogewinn-Werten des Dashboards.','Refresh'=>'Aktualisieren','How it works'=>'So funktioniert es','Connect each platform once. Tokens are encrypted on this server and never leave it.'=>'Verbinden Sie jede Plattform einmal. Tokens werden auf diesem Server verschlüsselt und verlassen ihn nie.','On first connect, the last 3 years of daily spend are loaded in the background (90-day chunks every 30 seconds).'=>'Beim ersten Verbinden werden die letzten 3 Jahre täglicher Ausgaben im Hintergrund geladen (90-Tage-Blöcke alle 30 Sekunden).','After that, the last 7 days are refreshed once per day to capture late corrections.'=>'Danach werden die letzten 7 Tage einmal pro Tag aktualisiert, um späte Korrekturen zu erfassen.','Spend is stored in the ad account currency. The dashboard shows ad-currency totals next to your store revenue so you can compare them directly.'=>'Die Ausgaben werden in der Währung des Werbekontos gespeichert. Das Dashboard zeigt die Summen in der Werbewährung neben Ihrem Shop-Umsatz an, sodass Sie sie direkt vergleichen können.','Recent errors'=>'Kürzliche Fehler','Last 50 entries from the sync log. Token values are redacted before storage.'=>'Letzte 50 Einträge aus dem Synchronisierungsprotokoll. Token-Werte werden vor der Speicherung unkenntlich gemacht.','View log'=>'Protokoll anzeigen','Clear log'=>'Protokoll leeren','System default'=>'Systemstandard','Appearance'=>'Erscheinungsbild','Customize how the BrikPanel admin interface looks. Changes apply to dashboard, products, orders, coupons, segments, the top bar, sidebar, and the modern login page. The rest of WordPress admin is untouched.'=>'Passen Sie das Aussehen der BrikPanel-Adminoberfläche an. Änderungen gelten für Dashboard, Produkte, Bestellungen, Gutscheine, Segmente, die obere Leiste, Seitenleiste und die moderne Anmeldeseite. Der Rest des WordPress-Admins bleibt unberührt.','Interface font'=>'Oberflächenschriftart','Pick the typeface used across BrikPanel. "System default" stays on your operating system\'s native font (no external request). Other choices load a single Google Fonts stylesheet with display: swap.'=>'Wählen Sie die in BrikPanel verwendete Schriftart. "Systemstandard" verbleibt auf der nativen Schrift Ihres Betriebssystems (keine externe Anfrage). Andere Optionen laden ein einzelnes Google Fonts-Stylesheet mit display: swap.','Accent color'=>'Akzentfarbe','Primary color used for buttons, focus rings, toggles, and active highlights. The BrikPanel default is a near-black gray (#303030); pick anything you like.'=>'Primärfarbe für Schaltflächen, Fokusringe, Schalter und aktive Hervorhebungen. Der BrikPanel-Standard ist ein fast schwarzes Grau (#303030); wählen Sie, was Ihnen gefällt.','Custom brand logo'=>'Eigenes Marken-Logo','Replace the BrikPanel mark in the admin top bar and on the modern login page with your own brand logo. When off, the default BrikPanel icon and your site name are shown.'=>'Ersetzen Sie das BrikPanel-Zeichen in der oberen Adminleiste und auf der modernen Anmeldeseite durch Ihr eigenes Marken-Logo. Wenn deaktiviert, werden das Standard-BrikPanel-Symbol und Ihr Website-Name angezeigt.','Brand logo image'=>'Marken-Logo-Bild','Pick an image from your media library, or paste an external image URL to load the logo from a CDN. When a URL is set it takes priority over the media library pick. The same logo is used in the admin top bar and on the modern login page. PNG or SVG with transparent background gives the cleanest result. Recommended size: 256×256 px or wider.'=>'Wählen Sie ein Bild aus Ihrer Mediathek oder fügen Sie eine externe Bild-URL ein, um das Logo von einem CDN zu laden. Wenn eine URL festgelegt ist, hat sie Vorrang vor der Auswahl aus der Mediathek. Dasselbe Logo wird in der oberen Verwaltungsleiste und auf der modernen Anmeldeseite verwendet. PNG oder SVG mit transparentem Hintergrund liefert das sauberste Ergebnis. Empfohlene Größe: 256×256 px oder breiter.','Custom CSS'=>'Eigenes CSS','Add your own CSS to fine-tune the BrikPanel interface — change button colors, backgrounds, spacing, and more. Your rules load last, so they override the built-in styles. Tip: prefix your selectors with a BrikPanel class (for example .brikpanel-dashboard, .brikpanel-topbar, .brikpanel-pe) so the changes stay inside BrikPanel and leave the rest of the admin untouched.'=>'Fügen Sie Ihr eigenes CSS hinzu, um die BrikPanel-Oberfläche fein abzustimmen: Ändern Sie Schaltflächenfarben, Hintergründe, Abstände und mehr. Ihre Regeln werden zuletzt geladen und überschreiben daher die integrierten Stile. Tipp: Stellen Sie Ihren Selektoren eine BrikPanel-Klasse voran (zum Beispiel .brikpanel-dashboard, .brikpanel-topbar, .brikpanel-pe), damit die Änderungen innerhalb von BrikPanel bleiben und den Rest der Verwaltung unberührt lassen.','No logo selected'=>'Kein Logo ausgewählt','Replace logo'=>'Logo ersetzen','Select logo'=>'Logo auswählen','Remove'=>'Entfernen','Or load from an image URL (CDN)'=>'Oder von einer Bild-URL laden (CDN)','Select brand logo'=>'Marken-Logo auswählen','Use this image'=>'Dieses Bild verwenden','Store Health'=>'Shop-Gesundheit','BrikControl scans your store in the background and flags issues, like products missing images, from the topbar shield, a dashboard banner, and its own Store Health page. Turn it off to hide all of that and stop the scheduled scans. Your latest results stay saved, so turning it back on restores them.'=>'BrikControl scannt Ihren Shop im Hintergrund und kennzeichnet Probleme, etwa Produkte ohne Bilder, über das Schild in der oberen Leiste, ein Dashboard-Banner und eine eigene Store-Health-Seite. Schalten Sie es aus, um all das auszublenden und die geplanten Scans zu stoppen. Ihre letzten Ergebnisse bleiben gespeichert, sodass das erneute Einschalten sie wiederherstellt.','Enable Store Health (BrikControl)'=>'Store Health aktivieren (BrikControl)','When on, the Store Health page, topbar shield, dashboard banner and daily background scans are active. When off, the entire module is dormant: no menu item, no topbar icon, no banner, and no scheduled scans.'=>'Wenn aktiviert, sind die Store-Health-Seite, das Schild in der oberen Leiste, das Dashboard-Banner und die täglichen Hintergrund-Scans aktiv. Wenn deaktiviert, ruht das gesamte Modul: kein Menüpunkt, kein Symbol in der oberen Leiste, kein Banner und keine geplanten Scans.','Product Image Health'=>'Produktbild-Gesundheit','Scanning… %1$s / %2$s products'=>'Scan… %1$s / %2$s Produkte','No product images found yet.'=>'Noch keine Produktbilder gefunden.','%1$s%% oversized (%2$s of %3$s) · %4$s%% modern format'=>'%1$s%% übergroß (%2$s von %3$s) · %4$s%% modernes Format','Add product images to start the health check.'=>'Fügen Sie Produktbilder hinzu, um die Gesundheitsprüfung zu starten.','%1$s product images are larger than 1 MB. Modern formats (WebP / AVIF) cover %2$s%% of your library. Missing files: %3$s.'=>'%1$s Produktbilder sind größer als 1 MB. Moderne Formate (WebP / AVIF) decken %2$s%% Ihrer Bibliothek ab. Fehlende Dateien: %3$s.','No products yet — nothing to check.'=>'Noch keine Produkte, nichts zu prüfen.','Add at least one published product to enable image health checks.'=>'Fügen Sie mindestens ein veröffentlichtes Produkt hinzu, um Bildgesundheitsprüfungen zu aktivieren.','Install %s to compress images and convert to WebP/AVIF automatically.'=>'Installieren Sie %s, um Bilder zu komprimieren und automatisch in WebP/AVIF zu konvertieren.','Install plugin'=>'Plugin installieren','%1$s product images (%2$s%%) are larger than 1 MB. These slow down your product pages and hurt SEO. Compress them to under 200 KB where possible.'=>'%1$s Produktbilder (%2$s%%) sind größer als 1 MB. Diese verlangsamen Ihre Produktseiten und schaden dem SEO. Komprimieren Sie sie nach Möglichkeit auf unter 200 KB.','Only %s%% of your product images use WebP / AVIF. Modern formats are 30–50%% smaller than JPEG/PNG with no visible quality loss.'=>'Nur %s%% Ihrer Produktbilder verwenden WebP / AVIF. Moderne Formate sind 30–50%% kleiner als JPEG/PNG ohne sichtbaren Qualitätsverlust.','%s product images point to files that no longer exist on disk. Re-upload them or detach the missing media references.'=>'%s Produktbilder verweisen auf Dateien, die nicht mehr auf der Festplatte existieren. Laden Sie sie erneut hoch oder lösen Sie die fehlenden Medienverweise.','Your product images are well-optimised. Keep an eye on this metric as you upload new products.'=>'Ihre Produktbilder sind gut optimiert. Behalten Sie diese Metrik im Auge, wenn Sie neue Produkte hochladen.','BrikControl: Full Health Scan'=>'BrikControl: Vollständiger Gesundheitsscan','Runs every BrikControl check and writes results to the dashboard.'=>'Führt jede BrikControl-Prüfung aus und schreibt die Ergebnisse in das Dashboard.','BrikControl: Scan Batch'=>'BrikControl: Scan-Batch','Processes a single batch of a long-running BrikControl check.'=>'Verarbeitet einen einzelnen Batch einer langlaufenden BrikControl-Prüfung.','Rescan now'=>'Jetzt erneut scannen','Scan queued — refreshing…'=>'Scan in Warteschlange, wird aktualisiert…','Could not start scan.'=>'Scan konnte nicht gestartet werden.','Not scanned yet'=>'Noch nicht gescannt','Scanning in background…'=>'Scan im Hintergrund…','just now'=>'gerade eben','Scanning {cursor} / {total} products…'=>'Scan {cursor} / {total} Produkte…','All checks passing'=>'Alle Prüfungen bestanden','Open Store Health'=>'Shop-Gesundheit öffnen','Last scan'=>'Letzter Scan','Scanning…'=>'Scan…','%s min ago'=>'vor %s Min.' . "\0" . 'vor %s Min.','%s h ago'=>'vor %s Std.' . "\0" . 'vor %s Std.','%s d ago'=>'vor %s Tag' . "\0" . 'vor %s Tagen','You do not have permission to access this page.'=>'Sie haben keine Berechtigung, auf diese Seite zuzugreifen.','Not scanned yet — run a scan to see results.'=>'Noch nicht gescannt, führen Sie einen Scan aus, um Ergebnisse zu sehen.','%s critical store health issue'=>'%s kritisches Shop-Gesundheitsproblem' . "\0" . '%s kritische Shop-Gesundheitsprobleme','%s store health warning'=>'%s Shop-Gesundheitswarnung' . "\0" . '%s Shop-Gesundheitswarnungen','Store health: all checks passing'=>'Shop-Gesundheit: Alle Prüfungen bestanden','Open full report'=>'Vollständigen Bericht öffnen','Run a scan to see store health checks.'=>'Führen Sie einen Scan aus, um Shop-Gesundheitsprüfungen zu sehen.','%s critical store health issue detected'=>'%s kritisches Shop-Gesundheitsproblem erkannt' . "\0" . '%s kritische Shop-Gesundheitsprobleme erkannt','Open the BrikControl report to see what to fix and which plugins can help.'=>'Öffnen Sie den BrikControl-Bericht, um zu sehen, was zu beheben ist und welche Plugins helfen können.','View report'=>'Bericht anzeigen','Dismiss for 7 days'=>'Für 7 Tage ausblenden','A scan is already running.'=>'Ein Scan läuft bereits.','Action Scheduler is unavailable.'=>'Action Scheduler ist nicht verfügbar.','Scan queued.'=>'Scan in Warteschlange.','A scan is already in the queue.'=>'Ein Scan befindet sich bereits in der Warteschlange.','Missing dismiss target.'=>'Fehlendes Ausblenden-Ziel.','Invalid nonce.'=>'Ungültige Nonce.','Last scan: %s'=>'Letzter Scan: %s','No scan completed yet.'=>'Noch kein Scan abgeschlossen.','Scan now'=>'Jetzt scannen','Critical'=>'Kritisch','Warnings'=>'Warnungen','OK'=>'OK','Pending'=>'Ausstehend','Scanning your store…'=>'Ihr Shop wird gescannt…','No checks registered yet. Once the first scan finishes, you will see results here.'=>'Noch keine Prüfungen registriert. Sobald der erste Scan abgeschlossen ist, sehen Sie hier Ergebnisse.','Warning'=>'Warnung','Health score'=>'Gesundheits-Score','Active optimizer plugins:'=>'Aktive Optimierungs-Plugins:','Open'=>'Öffnen','Total images'=>'Bilder insgesamt','Over 1 MB'=>'Über 1 MB','WebP / AVIF'=>'WebP / AVIF','JPEG / PNG'=>'JPEG / PNG','Missing files'=>'Fehlende Dateien','Largest images (top 10)'=>'Größte Bilder (Top 10)','Image'=>'Bild','Size'=>'Größe','Format'=>'Format','Action'=>'Aktion','(no title)'=>'(kein Titel)','Scanned %s'=>'Gescannt %s','Orders'=>'Bestellungen','Products'=>'Produkte','Analytics'=>'Analysen','Coupons'=>'Gutscheine','Search coupons...'=>'Gutscheine suchen...','Add coupon'=>'Gutschein hinzufügen','All'=>'Alle','Published'=>'Veröffentlicht','Draft'=>'Entwurf','Trash'=>'Papierkorb','Newest first'=>'Neueste zuerst','Oldest first'=>'Älteste zuerst','Code A-Z'=>'Code A-Z','Code Z-A'=>'Code Z-A','selected'=>'ausgewählt','Select all'=>'Alle auswählen','Deselect all'=>'Auswahl aufheben','Publish'=>'Veröffentlichen','Set as draft'=>'Als Entwurf festlegen','Move to trash'=>'In den Papierkorb verschieben','Code'=>'Code','Type'=>'Typ','Amount'=>'Betrag','Description'=>'Beschreibung','Usage / Limit'=>'Nutzung / Limit','Revenue'=>'Umsatz','Expiry date'=>'Ablaufdatum','Status'=>'Status','Edit coupon'=>'Gutschein bearbeiten','General'=>'Allgemein','Coupon code'=>'Gutscheincode','e.g. SUMMER2024'=>'z. B. SUMMER2024','Generate'=>'Generieren','Optional description for internal use'=>'Optionale Beschreibung für den internen Gebrauch','Discount type'=>'Rabatt-Typ','Percentage discount'=>'Prozentualer Rabatt','Fixed cart discount'=>'Fester Warenkorb-Rabatt','Fixed product discount'=>'Fester Produkt-Rabatt','Free shipping'=>'Kostenloser Versand','Usage restrictions'=>'Nutzungsbeschränkungen','Minimum spend'=>'Mindestbetrag','No minimum'=>'Kein Minimum','Maximum spend'=>'Höchstbetrag','No maximum'=>'Kein Maximum','Individual use only'=>'Nur Einzelverwendung','Cannot be used with other coupons'=>'Kann nicht mit anderen Gutscheinen verwendet werden','Exclude sale items'=>'Angebotsartikel ausschließen','Search products by name or SKU…'=>'Produkte nach Name oder SKU suchen…','Limit the coupon to these products. Leave empty to allow all products.'=>'Beschränken Sie den Gutschein auf diese Produkte. Leer lassen, um alle Produkte zuzulassen.','Exclude products'=>'Produkte ausschließen','Search products to exclude…'=>'Produkte zum Ausschließen suchen…','Coupon will not apply when the cart contains these products.'=>'Gutschein gilt nicht, wenn der Warenkorb diese Produkte enthält.','Product categories'=>'Produktkategorien','Search categories…'=>'Kategorien suchen…','Coupon applies only to products in these categories. Leave empty to allow all categories.'=>'Gutschein gilt nur für Produkte in diesen Kategorien. Leer lassen, um alle Kategorien zuzulassen.','Exclude categories'=>'Kategorien ausschließen','Search categories to exclude…'=>'Kategorien zum Ausschließen suchen…','Coupon will not apply to products in these categories.'=>'Gutschein gilt nicht für Produkte in diesen Kategorien.','Allowed emails'=>'Erlaubte E-Mails','e.g. jane@example.com, *@team.com'=>'z. B. jane@example.com, *@team.com','Comma- or newline-separated. Wildcards like *@example.com are supported.'=>'Komma- oder zeilenumbruchgetrennt. Platzhalter wie *@example.com werden unterstützt.','Usage limits'=>'Nutzungslimits','Usage limit per coupon'=>'Nutzungslimit pro Gutschein','Unlimited'=>'Unbegrenzt','Usage limit per user'=>'Nutzungslimit pro Benutzer','Limit usage to X items'=>'Nutzung auf X Artikel begrenzen','All matching items'=>'Alle passenden Artikel','Caps the number of matching items the discount applies to per cart. Only used with product or category restrictions.'=>'Begrenzt die Anzahl der passenden Artikel, auf die der Rabatt pro Warenkorb angewendet wird. Wird nur mit Produkt- oder Kategoriebeschränkungen verwendet.','Usage count'=>'Nutzungsanzahl','Cancel'=>'Abbrechen','Save changes'=>'Änderungen speichern','Coupon code is required.'=>'Gutscheincode ist erforderlich.','A coupon with this code already exists.'=>'Ein Gutschein mit diesem Code existiert bereits.','Coupon updated!'=>'Gutschein aktualisiert!','Coupon created!'=>'Gutschein erstellt!','Invalid coupon ID.'=>'Ungültige Gutschein-ID.','Coupon not found.'=>'Gutschein nicht gefunden.','Coupon permanently deleted.'=>'Gutschein dauerhaft gelöscht.','Coupon moved to trash.'=>'Gutschein in den Papierkorb verschoben.','Coupon status changed to %s.'=>'Gutscheinstatus geändert zu %s.','Coupon duplicated!'=>'Gutschein dupliziert!','(deleted product #%d)'=>'(gelöschtes Produkt #%d)','(deleted category #%d)'=>'(gelöschte Kategorie #%d)','Currency'=>'Währung','When your store takes orders in more than one currency, BrikPanel converts every order to your store currency before adding it up, so Revenue, Average Order Value and the sales chart are never a meaningless mix of currencies. If you use a multi-currency plugin such as CURCY, the exact rate from the day of each sale is read automatically from the order — you only need the rates below for currencies that arrive without one.'=>'Wenn Ihr Shop Bestellungen in mehr als einer Währung annimmt, rechnet BrikPanel jede Bestellung in Ihre Shop-Währung um, bevor sie addiert wird, damit Umsatz, durchschnittlicher Bestellwert und das Verkaufsdiagramm nie eine sinnlose Mischung aus Währungen sind. Wenn Sie ein Multi-Währungs-Plugin wie CURCY verwenden, wird der genaue Kurs vom Tag des jeweiligen Verkaufs automatisch aus der Bestellung gelesen. Sie benötigen die Kurse unten nur für Währungen, die ohne einen solchen eintreffen.','Exchange rates to your store currency'=>'Wechselkurse zu Ihrer Shop-Währung','Your store currency is %s. Enter how much one unit of each currency below is worth in it.'=>'Ihre Shop-Währung ist %s. Geben Sie ein, wie viel eine Einheit jeder Währung unten darin wert ist.','All of your orders are already in %s, so there is nothing to convert here.'=>'Alle Ihre Bestellungen sind bereits in %s, daher gibt es hier nichts umzurechnen.','Leave a rate empty to count those orders at their original number (no conversion). Orders that already carry a rate from your multi-currency plugin ignore the values here and always use their own day-of-sale rate.'=>'Lassen Sie einen Kurs leer, um diese Bestellungen mit ihrem ursprünglichen Wert zu zählen (keine Umrechnung). Bestellungen, die bereits einen Kurs aus Ihrem Multi-Währungs-Plugin tragen, ignorieren die Werte hier und verwenden immer ihren eigenen Kurs vom Verkaufstag.','Customer Analytics'=>'Kundenanalysen','Invalid request.'=>'Ungültige Anfrage.','User ID'=>'Benutzer-ID','Name'=>'Name','Email'=>'E-Mail','Phone'=>'Telefon','Order count'=>'Bestellanzahl','Total spent (LTV)'=>'Gesamtausgaben (LTV)','Average order value'=>'Durchschnittlicher Bestellwert','Recency (days)'=>'Aktualität (Tage)','First order'=>'Erste Bestellung','Last order'=>'Letzte Bestellung','Invalid segment.'=>'Ungültiges Segment.','Segment'=>'Segment','R'=>'R','F'=>'F','M'=>'M','Cohort month'=>'Kohorten-Monat','Period offset (months)'=>'Periodenversatz (Monate)','Cohort size'=>'Kohortengröße','Retained customers'=>'Gehaltene Kunden','Retention rate (%)'=>'Retentionsrate (%)','Action Scheduler is not available.'=>'Action Scheduler ist nicht verfügbar.','Customer metrics recomputed.'=>'Kundenmetriken neu berechnet.','User #%d'=>'Benutzer #%d','Exclusions saved.'=>'Ausschlüsse gespeichert.','Last refreshed: %s'=>'Zuletzt aktualisiert: %s','Not computed yet — running first sync…'=>'Noch nicht berechnet, erste Synchronisierung läuft…','Exclude customers'=>'Kunden ausschließen','Recompute now'=>'Jetzt neu berechnen','Export CSV'=>'CSV exportieren','Lifetime Value'=>'Lifetime Value','RFM Segments'=>'RFM-Segmente','Cohort Retention'=>'Kohorten-Retention','Total customers'=>'Gesamtkunden','Average LTV'=>'Durchschnittlicher LTV','Median:'=>'Median:','Total LTV'=>'Gesamter LTV','AOV:'=>'AOV:','Top customer'=>'Top-Kunde','highest lifetime spend'=>'höchste Lifetime-Ausgaben','LTV distribution'=>'LTV-Verteilung','How many customers fall into each lifetime-spend bracket.'=>'Wie viele Kunden in jede Lifetime-Ausgaben-Klasse fallen.','Top customers by LTV'=>'Top-Kunden nach LTV','Sorted by lifetime spend, descending. Click a row to open the customer profile.'=>'Sortiert nach Lifetime-Ausgaben, absteigend. Klicken Sie auf eine Zeile, um das Kundenprofil zu öffnen.','Customer'=>'Kunde','AOV'=>'AOV','LTV'=>'LTV','Recency'=>'Aktualität','Loading…'=>'Wird geladen…','Previous'=>'Zurück','Next'=>'Weiter','Customer segments'=>'Kundensegmente','Each customer is scored 1–5 on Recency, Frequency, and Monetary value, then placed into one of the RFM segments below. Click a card to drill into its customers.'=>'Jeder Kunde wird auf einer Skala von 1–5 nach Aktualität, Frequenz und monetärem Wert bewertet und dann einem der untenstehenden RFM-Segmente zugeordnet. Klicken Sie auf eine Karte, um in dessen Kunden einzutauchen.','Segment customers'=>'Segmentkunden','Export this segment (CSV)'=>'Dieses Segment exportieren (CSV)','Clear selection'=>'Auswahl löschen','RFM'=>'RFM','Click a segment above to load its customers.'=>'Klicken Sie auf ein Segment oben, um dessen Kunden zu laden.','Cohort retention'=>'Kohorten-Retention','Each row is a monthly cohort of customers acquired that month. Each cell shows the % of that cohort who placed at least one order N months later.'=>'Jede Zeile ist eine monatliche Kohorte von Kunden, die in diesem Monat gewonnen wurden. Jede Zelle zeigt den Prozentsatz dieser Kohorte, die N Monate später mindestens eine Bestellung aufgegeben hat.','Window:'=>'Zeitfenster:','Last 6 months'=>'Letzte 6 Monate','Last 12 months'=>'Letzte 12 Monate','Last 24 months'=>'Letzte 24 Monate','Average retention by month offset'=>'Durchschnittliche Retention nach Monatsversatz','Across all cohorts in the selected window — useful for spotting where the typical drop-off happens.'=>'Über alle Kohorten im gewählten Zeitfenster, nützlich, um zu erkennen, wo der typische Rückgang stattfindet.','Export matrix (CSV)'=>'Matrix exportieren (CSV)','Exclude customers from analytics'=>'Kunden aus der Analyse ausschließen','Close'=>'Schließen','Pick the accounts you do not want counted as customers, for example a point-of-sale or staff login that places many orders. Their orders still count toward your shop revenue and order totals, but they are left out of customer averages, segments, and retention so the numbers reflect your real customers.'=>'Wählen Sie die Konten aus, die nicht als Kunden gezählt werden sollen, zum Beispiel ein Kassen- oder Mitarbeiter-Login, das viele Bestellungen aufgibt. Ihre Bestellungen zählen weiterhin zu Ihrem Shop-Umsatz und den Bestellsummen, werden aber aus Kundendurchschnitten, Segmenten und der Kundenbindung herausgenommen, damit die Zahlen Ihre echten Kunden widerspiegeln.','People'=>'Personen','Search by name or email…'=>'Nach Name oder E-Mail suchen…','Roles'=>'Rollen','Everyone with a checked role is excluded too.'=>'Jeder mit einer angehakten Rolle wird ebenfalls ausgeschlossen.','Cost of goods'=>'Wareneinstand','Expenses (taxes, ad spend, supplier costs)'=>'Ausgaben (Steuern, Werbeausgaben, Lieferantenkosten)','Returns (refunds)'=>'Retouren (Rückerstattungen)','Coupons (discounts given)'=>'Gutscheine (gewährte Rabatte)','Move up'=>'Nach oben','Move down'=>'Nach unten','Reset to default'=>'Auf Standard zurücksetzen','Clearing cache…'=>'Cache wird geleert…','Cache could not be cleared.'=>'Cache konnte nicht geleert werden.','Toggle navigation'=>'Navigation umschalten','BrikPanel dashboard'=>'BrikPanel-Dashboard','Admin'=>'Administrator','Live visitors right now'=>'Live-Besucher jetzt','live'=>'live','Search orders'=>'Bestellungen suchen','Search'=>'Suche','Create'=>'Erstellen','New product'=>'Neues Produkt','New order'=>'Neue Bestellung','New coupon'=>'Neuer Gutschein','New post'=>'Neuer Beitrag','Order notifications'=>'Bestellbenachrichtigungen','Needs attention'=>'Benötigt Aufmerksamkeit','Processing orders'=>'Bestellungen in Bearbeitung','Pending payment'=>'Zahlung ausstehend','On hold'=>'In Wartestellung','Out of stock'=>'Nicht auf Lager','New customers today'=>'Neue Kunden heute','Hidden notices from other plugins'=>'Ausgeblendete Hinweise von anderen Plugins','Hidden notices'=>'Ausgeblendete Hinweise','From other plugins &amp; themes'=>'Von anderen Plugins &amp; Themes','View store'=>'Shop ansehen','Your profile'=>'Ihr Profil','BrikPanel settings'=>'BrikPanel-Einstellungen','Log out'=>'Abmelden','Purge %s'=>'%s leeren','Clear cache'=>'Cache leeren','Clear all caches'=>'Alle Caches leeren','Dashboard'=>'Dashboard','Profit (Revenue, Cost of goods, Net profit)'=>'Gewinn (Umsatz, Wareneinstand, Nettogewinn)','KPI cards (Sales, Orders, AOV, Visitors, Conversion)'=>'KPI-Karten (Verkäufe, Bestellungen, AOV, Besucher, Conversion)','Sales over time + Live visitors'=>'Verkäufe im Zeitverlauf + Live-Besucher','Conversion funnel + Order rates'=>'Conversion-Funnel + Bestellraten','Order locations globe + Top countries/cities'=>'Bestellungsstandorte-Globus + Top-Länder/-Städte','Top products + Recent orders'=>'Top-Produkte + Aktuelle Bestellungen','Most viewed pages + Most added to cart'=>'Meistbesuchte Seiten + Am häufigsten in den Warenkorb gelegt','Visitors by device + Customer types'=>'Besucher nach Gerät + Kundentypen','Customer segments (RFM)'=>'Kundensegmente (RFM)','Low stock + Customer lifetime value'=>'Niedriger Lagerbestand + Customer Lifetime Value','Subscriptions'=>'Abonnements','WordPress dashboard widgets'=>'WordPress-Dashboard-Widgets','Marketplace analytics (BrikMarket)'=>'Marktplatz-Analysen (BrikMarket)','With Marketplace'=>'Mit Marktplatz','Copy everything'=>'Alles kopieren','What does “Copy everything” do?'=>'Was bewirkt „Alles kopieren“?','Bundles your store’s key data — KPIs, top products, recent orders, customers and settings — into a single Markdown report and copies it to your clipboard. Paste it into ChatGPT, Claude or any AI tool to get instant analysis, insights and recommendations about your store.'=>'Bündelt die wichtigsten Daten Ihres Shops, KPIs, Top-Produkte, aktuelle Bestellungen, Kunden und Einstellungen, in einen einzigen Markdown-Bericht und kopiert ihn in die Zwischenablage. Fügen Sie ihn in ChatGPT, Claude oder ein beliebiges KI-Tool ein, um sofortige Analysen, Erkenntnisse und Empfehlungen zu Ihrem Shop zu erhalten.','Ad spend settings'=>'Werbeausgaben-Einstellungen','Connect ad accounts'=>'Werbekonten verbinden','Download the selected period as an Excel workbook (opens in Excel / Google Sheets)'=>'Den ausgewählten Zeitraum als Excel-Arbeitsmappe herunterladen (wird in Excel / Google Sheets geöffnet)','Export Excel'=>'Excel exportieren','Today'=>'Heute','Yesterday'=>'Gestern','Last 7 Days'=>'Letzte 7 Tage','Last 30 Days'=>'Letzte 30 Tage','Last 90 Days'=>'Letzte 90 Tage','Custom'=>'Benutzerdefiniert','Select dates'=>'Datum auswählen','Where this data comes from'=>'Woher diese Daten stammen','BrikPanel started measuring visitors and conversions on %s, the day it was activated. There is no visitor history before that date, so a recent install can read low or empty here. Your sales and orders are not affected. Those use your full WooCommerce history.'=>'BrikPanel hat am %s mit der Messung von Besuchern und Conversions begonnen, dem Tag der Aktivierung. Vor diesem Datum gibt es keinen Besucherverlauf, sodass eine kürzlich erfolgte Installation hier niedrige oder leere Werte anzeigen kann. Ihre Verkäufe und Bestellungen sind nicht betroffen. Diese nutzen Ihren gesamten WooCommerce-Verlauf.','BrikPanel measures visitors and conversions from the day it was activated. There is no visitor history before that, so a recent install can read low or empty here. Your sales and orders are not affected. Those use your full WooCommerce history.'=>'BrikPanel misst Besucher und Conversions ab dem Tag der Aktivierung. Davor gibt es keinen Besucherverlauf, sodass eine kürzlich erfolgte Installation hier niedrige oder leere Werte anzeigen kann. Ihre Verkäufe und Bestellungen sind nicht betroffen. Diese nutzen Ihren gesamten WooCommerce-Verlauf.','About these numbers'=>'Über diese Zahlen','Sales, orders, profit and customer figures use your full WooCommerce order history.'=>'Verkaufs-, Bestell-, Gewinn- und Kundenzahlen nutzen Ihren gesamten WooCommerce-Bestellverlauf.','Visitors, conversion rate and the funnel are measured by BrikPanel from %s, the day it was activated, so they have no earlier history.'=>'Besucher, Conversion-Rate und der Funnel werden von BrikPanel ab dem %s, dem Tag der Aktivierung, gemessen, sodass sie keinen früheren Verlauf haben.','Visitors, conversion rate and the funnel are measured by BrikPanel from the day it was activated, so they have no earlier history.'=>'Besucher, Conversion-Rate und der Funnel werden von BrikPanel ab dem Tag der Aktivierung gemessen, sodass sie keinen früheren Verlauf haben.','Orders placed by store administrators are left out of every figure, so your own test orders do not change the totals.'=>'Von Shop-Administratoren aufgegebene Bestellungen werden aus jeder Zahl herausgenommen, sodass Ihre eigenen Testbestellungen die Summen nicht verändern.','Why this can look low'=>'Warum dies niedrig erscheinen kann','Orders placed by store administrators are not counted here, so test orders you place on your own admin account do not change this figure. Real customer orders are always included.'=>'Von Shop-Administratoren aufgegebene Bestellungen werden hier nicht gezählt, sodass Testbestellungen, die Sie über Ihr eigenes Administratorkonto aufgeben, diese Zahl nicht verändern. Echte Kundenbestellungen sind immer enthalten.','Total Sales'=>'Gesamtumsatz','Avg. Order Value'=>'Durchschn. Bestellwert','Visitors'=>'Besucher','Conversion Rate'=>'Conversion-Rate','The total of all paid orders for the selected dates (Processing and Completed by default), with tax and shipping included and any customer refunds in the period subtracted. Orders placed by store administrators are left out so your own test orders do not change it. You can change which statuses count under Settings, then Analytics.'=>'Die Summe aller bezahlten Bestellungen für die ausgewählten Daten (standardmäßig In Bearbeitung und Abgeschlossen), inklusive Steuer und Versand und abzüglich aller Kundenrückerstattungen im Zeitraum. Von Shop-Administratoren aufgegebene Bestellungen werden ausgelassen, damit Ihre eigenen Testbestellungen sie nicht verändern. Sie können unter Einstellungen, dann Analyse ändern, welche Status zählen.','The total of all paid orders for the selected dates (Processing and Completed by default), with tax and shipping included. Orders placed by store administrators are left out so your own test orders do not change it. You can change which statuses count under Settings, then Analytics.'=>'Die Summe aller bezahlten Bestellungen für die ausgewählten Daten (standardmäßig In Bearbeitung und Abgeschlossen), inklusive Steuer und Versand. Von Shop-Administratoren aufgegebene Bestellungen werden ausgelassen, damit Ihre eigenen Testbestellungen sie nicht verändern. Sie können unter Einstellungen, dann Analyse ändern, welche Status zählen.','How Revenue is calculated'=>'Wie der Umsatz berechnet wird','Show revenue breakdown'=>'Umsatzaufschlüsselung anzeigen','Cost of Goods'=>'Wareneinstand','How Cost of Goods is calculated'=>'Wie der Wareneinstand berechnet wird','The "Cost of goods" you set on each product, multiplied by the quantity sold in paid orders for the period. Variations use their own cost and fall back to the parent product. Any product with no cost set counts as zero, which overstates Net profit, so fill those in for an accurate margin.'=>'Der "Wareneinstand", den Sie für jedes Produkt festlegen, multipliziert mit der in bezahlten Bestellungen des Zeitraums verkauften Menge. Variationen verwenden ihre eigenen Kosten und greifen ersatzweise auf das übergeordnete Produkt zurück. Jedes Produkt ohne festgelegte Kosten zählt als null, was den Nettogewinn zu hoch ausweist, also tragen Sie diese für eine genaue Marge ein.','Expenses'=>'Ausgaben','What Expenses includes'=>'Was die Ausgaben umfassen','Operating costs for the period: order tax, ad spend from connected ad platforms (store currency only), supplier and stock costs from received purchase orders, plus anything logged in the Expenses module. Open the breakdown to see each part.'=>'Betriebskosten für den Zeitraum: Bestellsteuer, Werbeausgaben von verbundenen Werbeplattformen (nur in Shop-Währung), Lieferanten- und Bestandskosten aus erhaltenen Bestellungen sowie alles, was im Ausgaben-Modul erfasst wurde. Öffnen Sie die Aufschlüsselung, um jeden Teil zu sehen.','Add expense'=>'Ausgabe hinzufügen','Show expense breakdown'=>'Ausgabenaufschlüsselung anzeigen','Net Profit'=>'Nettogewinn','How Net Profit is calculated'=>'Wie der Nettogewinn berechnet wird','Revenue minus Cost of goods minus Expenses. This is what is left after the cost of what you sold and your operating costs for the period. A negative figure means a loss.'=>'Umsatz minus Wareneinstand minus Ausgaben. Das ist, was nach den Kosten für das Verkaufte und Ihren Betriebskosten für den Zeitraum übrig bleibt. Ein negativer Wert bedeutet einen Verlust.','Fixed amount'=>'Fester Betrag','Percentage of revenue'=>'Prozentsatz des Umsatzes','Title'=>'Titel','e.g. Rent, Salaries, Credit card commission'=>'z. B. Miete, Gehälter, Kreditkartenprovision','Date'=>'Datum','Repeats'=>'Wiederholungen','One-time'=>'Einmalig','Monthly'=>'Monatlich','Weekly'=>'Wöchentlich','Yearly'=>'Jährlich','Note (optional)'=>'Notiz (optional)','What is this for?'=>'Wofür ist das?','A repeating expense is counted automatically in every period from this date onward.'=>'Eine wiederkehrende Ausgabe wird ab diesem Datum automatisch in jedem Zeitraum gezählt.','A percentage cost is applied to your revenue in every period from this date onward (great for card or marketplace commission).'=>'Eine prozentuale Kostenstelle wird ab diesem Datum in jedem Zeitraum auf Ihren Umsatz angewendet (ideal für Karten- oder Marktplatzprovisionen).','Save expense'=>'Ausgabe speichern','Marketplace Sales'=>'Marktplatz-Verkäufe','Marketplace Orders'=>'Marktplatz-Bestellungen','Avg. Marketplace Order'=>'Durchschn. Marktplatz-Bestellung','Share of Total Revenue'=>'Anteil am Gesamtumsatz','Revenue by Marketplace'=>'Umsatz nach Marktplatz','Loading...'=>'Wird geladen...','Marketplace Share'=>'Marktplatz-Anteil','Top Categories from Marketplaces'=>'Top-Kategorien von Marktplätzen','Top Marketplace Products'=>'Top-Marktplatz-Produkte','Sales Over Time'=>'Verkäufe im Zeitverlauf','Live Visitors'=>'Live-Besucher','No active visitors'=>'Keine aktiven Besucher','Conversion Funnel'=>'Conversion-Funnel','Order Rates'=>'Bestellraten','Order Locations'=>'Bestellungsstandorte','View mode'=>'Ansichtsmodus','Customers'=>'Kunden','Toggle theme'=>'Theme umschalten','Top Countries'=>'Top-Länder','Top Cities'=>'Top-Städte','Top Products'=>'Top-Produkte','Recent Orders'=>'Aktuelle Bestellungen','Most Viewed Pages'=>'Meistbesuchte Seiten','Most Added to Cart'=>'Am häufigsten in den Warenkorb gelegt','Visitors by Device'=>'Besucher nach Gerät','Device breakdown view'=>'Geräte-Aufschlüsselungsansicht','Customer Types'=>'Kundentypen','Customer Segments (RFM)'=>'Kundensegmente (RFM)','View details →'=>'Details anzeigen →','Low Stock'=>'Niedriger Lagerbestand','Customer Lifetime Value'=>'Customer Lifetime Value','WordPress widgets'=>'WordPress-Widgets','Widget failed to load.'=>'Widget konnte nicht geladen werden.','Active'=>'Aktiv','Cancelled'=>'Storniert','Expired'=>'Abgelaufen','Pending cancellation'=>'Stornierung ausstehend','Tax'=>'Steuer','Other'=>'Sonstige','Supplier / stock'=>'Lieferant / Bestand','Gross sales'=>'Bruttoumsatz','Returns'=>'Retouren','Coupons (already in totals)'=>'Gutscheine (bereits in den Summen)','Custom range'=>'Benutzerdefinierter Bereich','%d day'=>'%d Tag' . "\0" . '%d Tage','Guest'=>'Gast','Organic'=>'Organisch','Referral'=>'Verweis','Campaign'=>'Kampagne','Direct'=>'Direkt','You do not have permission to export dashboard data.'=>'Sie haben keine Berechtigung, Dashboard-Daten zu exportieren.','Export engine unavailable on this server.'=>'Export-Engine auf diesem Server nicht verfügbar.','New'=>'Neu','BrikPanel Report'=>'BrikPanel-Bericht','Website'=>'Website','Report period'=>'Berichtszeitraum','From'=>'Von','To'=>'Bis','Duration'=>'Dauer','Generated'=>'Erstellt','Key Metrics'=>'Kennzahlen','Metric'=>'Metrik','Value'=>'Wert','Change vs previous period'=>'Veränderung zur Vorperiode','Conversion Rate (%)'=>'Conversion-Rate (%)','Profit'=>'Gewinn','Amount (%s)'=>'Betrag (%s)','Context'=>'Kontext','Same as Total Sales'=>'Wie Gesamtumsatz','%s%% of revenue'=>'%s%% des Umsatzes','%s%% margin'=>'%s%% Marge','Returns & Refunds'=>'Retouren & Rückerstattungen','Returned / refunded orders'=>'Retournierte / erstattete 